function geoName(path, lang) {
  let pool = GEO,
    node = null;
  for (const seg of path.split('.')) {
    node = (pool || []).find(n => n.code === seg || n.path.endsWith('.' + seg) || n.path === seg);
    if (!node) return path;
    pool = node.children;
  }
  return lang === 'en' ? node.nameEn : node.name;
}
function geoLabel(path, lang, from = 2) {
  const parts = path.split('.');
  const out = [];
  let pool = GEO;
  for (let i = 0; i < parts.length; i++) {
    const node = (pool || []).find(n => n.path === parts.slice(0, i + 1).join('.'));
    if (!node) break;
    if (i >= from) out.push(lang === 'en' ? node.nameEn : node.name);
    pool = node.children;
  }
  return out.join(' › ');
}

