/* ── Products (§5.5 real ×2 + fixture ×10). Shape = ProductDetailResponseDto ── */
function P(n, slug, name, nameEn, minor, storeN, catN, variants, desc, descEn, attrs = [], fixture = false, ratio) {
  const store = storeById(ID(storeN));
  const vs = variants.map(([vn, vnEn, vMinor, inStock], i) => ({
    id: ID(n + '1' + i),
    name: vn,
    nameEn: vnEn,
    price: M(vMinor ?? minor),
    inStock: inStock !== false
  }));
  return {
    id: ID(n),
    slug,
    name,
    nameEn,
    price: M(minor),
    imageUrl: '',
    storeId: store.id,
    storeName: store.name,
    storeNameEn: store.nameEn,
    categoryId: ID(catN),
    description: desc,
    descriptionEn: descEn,
    variants: vs,
    media: [{
      assetId: ID(n + '4'),
      urls: IMG(slug)
    }],
    store: {
      id: store.id,
      slug: store.slug,
      name: store.name,
      marketCode: store.marketCode
    },
    attributes: attrs.map(([code, an, anEn, v, vEn]) => ({
      code,
      name: an,
      nameEn: anEn,
      value: v,
      valueEn: vEn
    })),
    fixture
  };
}
